typedef struct drawable_vtable {
  void (*draw)(const void *self, FILE *out);
  void *(*clone)(const void *self);
  void (*destroy)(void *self);
} drawable_vtable;

typedef struct { const drawable_vtable *vt; void *self; } drawable;

static void drawable_draw(const drawable *d, FILE *out) {
  d->vt->draw(d->self, out);        /* dispatch: the concrete type is gone */
}
